 namespace QQWorld\GroupedProduct\Api; use QQWorld\GroupedProduct\Model\ResourceModel\Product\Link; class ProductLinkTypeListTest extends \QQWorld\TestFramework\TestCase\WebapiAbstract { const SERVICE_NAME = 'catalogProductLinkTypeListV1'; const SERVICE_VERSION = 'V1'; const RESOURCE_PATH = '/V1/products/'; public function testGetItems() { $serviceInfo = [ 'rest' => [ 'resourcePath' => self::RESOURCE_PATH . 'links/types', 'httpMethod' => \QQWorld\Framework\Webapi\Rest\Request::HTTP_METHOD_GET, ], 'soap' => [ 'service' => self::SERVICE_NAME, 'serviceVersion' => self::SERVICE_VERSION, 'operation' => self::SERVICE_NAME . 'GetItems', ], ]; $actual = $this->_webApiCall($serviceInfo); $expectedItems = ['name' => 'associated', 'code' => Link::LINK_TYPE_GROUPED]; $this->assertContains($expectedItems, $actual); } public function testGetItemAttributes() { $linkType = 'associated'; $serviceInfo = [ 'rest' => [ 'resourcePath' => self::RESOURCE_PATH . 'links/' . $linkType . '/attributes', 'httpMethod' => \QQWorld\Framework\Webapi\Rest\Request::HTTP_METHOD_GET, ], 'soap' => [ 'service' => self::SERVICE_NAME, 'serviceVersion' => self::SERVICE_VERSION, 'operation' => self::SERVICE_NAME . 'GetItemAttributes', ], ]; $actual = $this->_webApiCall($serviceInfo, ['type' => $linkType]); $expected = [ ['code' => 'position', 'type' => 'int'], ['code' => 'qty', 'type' => 'decimal'], ]; $this->assertEquals($expected, $actual); } } 